-- One-time transfer from the public FAQ page to the admin-managed source.
-- Preserve existing IDs, content, attachments, visibility and ordering on a match.
-- Negative positions keep the former introductory questions before existing FAQ.
-- No runtime seeding: questions hidden/deleted later stay hidden/deleted.
WITH imported ("id", "title", "answer", "contentJson", "category", "sortOrder") AS (
  VALUES
  ('static-secure-account', 'Как обезопасить свой аккаунт?', 'Привяжите к профилю несколько способов входа: Telegram, почту, VK и пароль. Если один способ временно недоступен, вы сможете зайти другим и не потеряете доступ к турнирам, матчам и заказам.

Используйте уникальный пароль, который не повторяется на других сайтах. Не отправляйте пароль, коды входа и ссылки подтверждения другим людям, даже если они представляются администрацией.

После настройки способов входа периодически проверяйте раздел безопасности в профиле. Если увидели незнакомый вход, сразу смените пароль и завершите лишние сессии.', '[{"type":"text","text":"Привяжите к профилю несколько способов входа: Telegram, почту, VK и пароль. Если один способ временно недоступен, вы сможете зайти другим и не потеряете доступ к турнирам, матчам и заказам."},{"type":"text","text":"Используйте уникальный пароль, который не повторяется на других сайтах. Не отправляйте пароль, коды входа и ссылки подтверждения другим людям, даже если они представляются администрацией."},{"type":"text","text":"После настройки способов входа периодически проверяйте раздел безопасности в профиле. Если увидели незнакомый вход, сразу смените пароль и завершите лишние сессии."}]', 'Безопасность аккаунта', -100),
  ('static-link-telegram', 'Как привязать Telegram?', 'Откройте профиль и перейдите в настройки безопасности. В блоке Telegram нажмите кнопку привязки и следуйте подсказке сайта.

После перехода в Telegram нажмите Start или подтвердите привязку через кнопку бота. Возвращайтесь на сайт только после того, как Telegram покажет, что бот запущен.

Telegram нужен для быстрого входа, важных уведомлений, кодов безопасности и восстановления доступа. Если бот заблокирован или чат с ним не начат, уведомления в Telegram приходить не будут.', '[{"type":"text","text":"Откройте профиль и перейдите в настройки безопасности. В блоке Telegram нажмите кнопку привязки и следуйте подсказке сайта."},{"type":"text","text":"После перехода в Telegram нажмите Start или подтвердите привязку через кнопку бота. Возвращайтесь на сайт только после того, как Telegram покажет, что бот запущен."},{"type":"text","text":"Telegram нужен для быстрого входа, важных уведомлений, кодов безопасности и восстановления доступа. Если бот заблокирован или чат с ним не начат, уведомления в Telegram приходить не будут."}]', 'Безопасность аккаунта', -99),
  ('static-link-email', 'Как привязать почту?', 'В профиле откройте настройки безопасности, укажите актуальный email и сохраните изменения. Лучше использовать почту, к которой у вас точно есть постоянный доступ.

После сохранения откройте письмо от сайта и перейдите по ссылке подтверждения. Если письма нет, проверьте Спам, Промоакции и правильность введенного адреса.

Подтвержденная почта помогает восстановить аккаунт, получать важные сообщения и доказывает, что адрес действительно принадлежит вам.', '[{"type":"text","text":"В профиле откройте настройки безопасности, укажите актуальный email и сохраните изменения. Лучше использовать почту, к которой у вас точно есть постоянный доступ."},{"type":"text","text":"После сохранения откройте письмо от сайта и перейдите по ссылке подтверждения. Если письма нет, проверьте Спам, Промоакции и правильность введенного адреса."},{"type":"text","text":"Подтвержденная почта помогает восстановить аккаунт, получать важные сообщения и доказывает, что адрес действительно принадлежит вам."}]', 'Безопасность аккаунта', -98),
  ('static-link-vk', 'Как привязать VK?', 'Откройте настройки безопасности в профиле и выберите привязку VK. Сайт перенаправит вас на авторизацию VK ID.

Войдите в нужный VK-аккаунт и разрешите привязку. После возврата на сайт проверьте, что VK появился среди способов входа.

Привязывайте только свой личный VK. Не используйте чужой аккаунт, потому что через него можно будет входить в ваш профиль.', '[{"type":"text","text":"Откройте настройки безопасности в профиле и выберите привязку VK. Сайт перенаправит вас на авторизацию VK ID."},{"type":"text","text":"Войдите в нужный VK-аккаунт и разрешите привязку. После возврата на сайт проверьте, что VK появился среди способов входа."},{"type":"text","text":"Привязывайте только свой личный VK. Не используйте чужой аккаунт, потому что через него можно будет входить в ваш профиль."}]', 'Безопасность аккаунта', -97),
  ('static-password', 'Как создать или сменить пароль?', 'Перейдите в профиль, откройте настройки безопасности и найдите блок пароля. Если пароля еще нет, выберите создание пароля; если пароль уже есть, используйте смену пароля.

Хороший пароль должен быть длинным, уникальным и не состоять только из имени, даты рождения, ника или названия клуба. Лучше использовать сочетание букв, цифр и символов.

После смены пароля сохраните его в надежном менеджере паролей. Если подозреваете, что кто-то узнал пароль, сразу смените его и проверьте активные сессии.', '[{"type":"text","text":"Перейдите в профиль, откройте настройки безопасности и найдите блок пароля. Если пароля еще нет, выберите создание пароля; если пароль уже есть, используйте смену пароля."},{"type":"text","text":"Хороший пароль должен быть длинным, уникальным и не состоять только из имени, даты рождения, ника или названия клуба. Лучше использовать сочетание букв, цифр и символов."},{"type":"text","text":"После смены пароля сохраните его в надежном менеджере паролей. Если подозреваете, что кто-то узнал пароль, сразу смените его и проверьте активные сессии."}]', 'Безопасность аккаунта', -96),
  ('static-reliability-what', 'Что такое надежность?', 'Надежность - это показатель дисциплины игрока от 0 до 100. Он показывает, насколько стабильно игрок подтверждает результаты, доигрывает матчи без технических поражений и не создает спорные ситуации.

Система нужна не для наказаний ради наказаний, а для защиты турниров: участники быстрее понимают, кому можно доверять расписание матча, а администрация видит повторяющиеся нарушения.

Показатель виден в профиле сразу под рейтингом. Там же отображаются текущий статус, серии подтверждений, чистые матчи подряд и последние изменения надежности.', '[{"type":"text","text":"Надежность - это показатель дисциплины игрока от 0 до 100. Он показывает, насколько стабильно игрок подтверждает результаты, доигрывает матчи без технических поражений и не создает спорные ситуации."},{"type":"text","text":"Система нужна не для наказаний ради наказаний, а для защиты турниров: участники быстрее понимают, кому можно доверять расписание матча, а администрация видит повторяющиеся нарушения."},{"type":"text","text":"Показатель виден в профиле сразу под рейтингом. Там же отображаются текущий статус, серии подтверждений, чистые матчи подряд и последние изменения надежности."}]', 'Надёжность', -95),
  ('static-reliability-statuses', 'Какие бывают статусы надежности?', '90-100 - отличная надежность. Игрок стабильно закрывает матчи без нарушений.

80-89 - хорошая надежность. Игрок допущен к турнирам, но системе уже есть что отслеживать.

70-79 - допущен. Игрок может регистрироваться, но ему важно избегать технических поражений и спорных результатов.

Ниже 70 - ограничен. Регистрация в новые турниры временно закрывается, пока ограничение не закончится или показатель не будет восстановлен правилами системы.', '[{"type":"text","text":"90-100 - отличная надежность. Игрок стабильно закрывает матчи без нарушений."},{"type":"text","text":"80-89 - хорошая надежность. Игрок допущен к турнирам, но системе уже есть что отслеживать."},{"type":"text","text":"70-79 - допущен. Игрок может регистрироваться, но ему важно избегать технических поражений и спорных результатов."},{"type":"text","text":"Ниже 70 - ограничен. Регистрация в новые турниры временно закрывается, пока ограничение не закончится или показатель не будет восстановлен правилами системы."}]', 'Надёжность', -94),
  ('static-reliability-raise', 'Как повысить надежность?', 'Подтверждайте результаты вовремя и без задержек. За каждые 10 подтверждений подряд система добавляет +3 к надежности.

Играйте матчи без технических поражений и нарушений. За каждые 10 чистых матчей подряд система добавляет +4 к надежности.

Надежность не растет выше 100. Если у игрока уже максимум, бонусы фиксируются в истории, но итоговое значение остается 100/100.', '[{"type":"text","text":"Подтверждайте результаты вовремя и без задержек. За каждые 10 подтверждений подряд система добавляет +3 к надежности."},{"type":"text","text":"Играйте матчи без технических поражений и нарушений. За каждые 10 чистых матчей подряд система добавляет +4 к надежности."},{"type":"text","text":"Надежность не растет выше 100. Если у игрока уже максимум, бонусы фиксируются в истории, но итоговое значение остается 100/100."}]', 'Надёжность', -93),
  ('static-reliability-drop', 'За что надежность снижается?', 'Техническое поражение снижает надежность на 8 пунктов. Это применяется, когда матч завершен форфейтом и система определила проигравшую сторону.

Если за последние 30 дней уже было техническое поражение, повторное нарушение жестче влияет на профиль: при надежности 80 и выше показатель опускается до 80, а при надежности ниже 80 снимается еще 10 пунктов.

Негативные события сбрасывают серии подтверждений и чистых матчей. Поэтому после нарушения бонусные серии нужно набирать заново.', '[{"type":"text","text":"Техническое поражение снижает надежность на 8 пунктов. Это применяется, когда матч завершен форфейтом и система определила проигравшую сторону."},{"type":"text","text":"Если за последние 30 дней уже было техническое поражение, повторное нарушение жестче влияет на профиль: при надежности 80 и выше показатель опускается до 80, а при надежности ниже 80 снимается еще 10 пунктов."},{"type":"text","text":"Негативные события сбрасывают серии подтверждений и чистых матчей. Поэтому после нарушения бонусные серии нужно набирать заново."}]', 'Надёжность', -92),
  ('static-reliability-restriction', 'Что происходит при ограничении?', 'Если надежность падает ниже 70, регистрация в новые турниры закрывается на 30 дней. Уже сохраненная история матчей и статистика не удаляются.

После окончания срока система восстанавливает игрока для повторного допуска: надежность повышается на 10 пунктов, но не выше 80. Если этого достаточно для порога допуска, ограничение снимается.

Ограничение не скрывает профиль и не удаляет достижения. Оно только защищает новые турниры от повторных срывов регистрации и матчей.', '[{"type":"text","text":"Если надежность падает ниже 70, регистрация в новые турниры закрывается на 30 дней. Уже сохраненная история матчей и статистика не удаляются."},{"type":"text","text":"После окончания срока система восстанавливает игрока для повторного допуска: надежность повышается на 10 пунктов, но не выше 80. Если этого достаточно для порога допуска, ограничение снимается."},{"type":"text","text":"Ограничение не скрывает профиль и не удаляет достижения. Оно только защищает новые турниры от повторных срывов регистрации и матчей."}]', 'Надёжность', -91)
)
INSERT INTO "FaqItem" ("id", "title", "answer", "contentJson", "category", "sortOrder", "isPublished", "createdAt", "updatedAt")
SELECT imported."id", imported."title", imported."answer", imported."contentJson", imported."category", imported."sortOrder", true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM imported
WHERE NOT EXISTS (
  SELECT 1 FROM "FaqItem" existing
  WHERE existing."id" = imported."id"
     OR lower(regexp_replace(btrim(existing."title"), '\s+', ' ', 'g')) = lower(regexp_replace(btrim(imported."title"), '\s+', ' ', 'g'))
)
ON CONFLICT ("id") DO NOTHING;
